  static void Output(object rgb,int rgbPort,object alpha,int alphaPort,object position=null,int positionPort=0)
  {
   foreach(var ctxName in new[]{"fragmentContext","vertexContext"})foreach(var reference in GraphReflect.List(GraphReflect.Get(GraphReflect.Get(graph,ctxName),"blocks"))){var block=GraphReflect.Get(reference,"value");string name=GraphReflect.Get(GraphReflect.Get(block,"descriptor"),"name").ToString();if(name.Contains("BaseColor"))Link(rgb,rgbPort,block,0);else if(name=="Alpha")Link(alpha,alphaPort,block,0);else if(name=="Position"&&position!=null)Link(position,positionPort,block,0);}
  }
  static void WriteAdvanced(string name){string path=Advanced+"Graphs/"+name+".shadergraph";File.WriteAllText(path,GraphReflect.Call(GraphReflect.T(SG+"Serialization.MultiJson"),"Serialize",graph).ToString());AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);}
